# FP-Growth Research Pipeline
# Mengikuti notebook penelitian Delite:
# - split kategori menggunakan ';'
# - kategori resmi 6 layanan
# - support 0.05
# - confidence 0.50
# - lift > 1.00

# ==============================
# DATA INPUT ENGINE
# ==============================

# Keterangan istilah layanan untuk pengguna non-teknis
SERVICE_ALIAS = {
    "Brand Activation Consultant": "Brand Activation (konsultasi aktivasi merek/strategi pengalaman brand)",
    "Community Program": "Community Program (program pengelolaan komunitas dan keterlibatan audiens)",
    "Podcast Production House": "Podcast Production House (produksi konten podcast)",
    "Event Management Service": "Event Management Service (layanan pengelolaan acara)"
}

MASTER_LAYANAN = [
    "Podcast Production House",
    "Event Management Service",
    "Merchandise Production",
    "Brand Activation Consultant",
    "Community Program",
    "Out Of Home (OOH)"
]

