def clean_category(value):
    """
    Membersihkan kategori tanpa mengubah makna bisnis.
    Multi layanan seperti:
    'Community Program; Brand Activation Consultant'
    dianggap valid dan dipertahankan untuk FP-Growth.
    """
    if pd.isna(value):
        return value

    value = str(value).strip()
    value = value.replace(";", ",")
    parts = [x.strip() for x in value.split(",") if x.strip()]

    fixed = []
    for p in parts:
        # Normalisasi ringan hanya untuk spasi/huruf, tidak menghapus kategori
        normalized = " ".join(p.split())

        match = get_close_matches(
            normalized,
            MASTER_LAYANAN,
            n=1,
            cutoff=0.85
        )

        # typo kecil boleh diperbaiki, kategori valid tetap dipertahankan
        fixed.append(match[0] if match else normalized)

    return ", ".join(fixed)


def validate_transaction(df):
    warnings=[]
    required=["Nomor Transaksi","Kategori Layanan","Client"]
    if "Item" in df.columns:
        item_col="Item"
    elif "Deskripsi Item" in df.columns:
        item_col="Deskripsi Item"
        df["Item"]=df[item_col]
    else:
        return None,["Kolom Item/Deskripsi Item tidak ditemukan."]

    required=["Nomor Transaksi","Kategori Layanan","Item","Client"]
    missing=[x for x in required if x not in df.columns]
    if missing:
        return None,[f"Kolom tidak ditemukan: {', '.join(missing)}"]

    df=df[required].copy()

    for c in required:
        df[c]=df[c].fillna("").astype(str).str.strip()

    category_normalized = 0
    empty_count = 0

    for idx,row in df.iterrows():
        if row["Kategori Layanan"]:
            old=row["Kategori Layanan"]
            new=clean_category(old)
            if old != new:
                category_normalized += 1
            df.loc[idx,"Kategori Layanan"] = new

        if any(row[c] == "" for c in required):
            empty_count += 1

    if category_normalized > 0:
        warnings.append(
            f"Normalisasi penulisan kategori: {category_normalized} transaksi disesuaikan otomatis."
        )

    if empty_count > 0:
        warnings.append(
            f"Data belum lengkap: {empty_count} transaksi memiliki kolom kosong."
        )

    if not warnings:
        warnings.append(
            "Dataset berhasil dibersihkan. Tidak ditemukan perbaikan kategori layanan."
        )

    return df,warnings

def format_item(x):
    return str(x).replace("{","").replace("}","")




# v3: recommendation layer mengikuti hasil association rule penelitian

def generate_analysis_from_raw(encoding):
    """
    Pipeline sesuai penelitian Delite:
    - basket transaction dari kategori layanan
    - one-hot encoding
    - FP-Growth dengan support 5%
    - association rule confidence 50%, lift > 1
    - rekomendasi hanya berasal dari association rules
    """
    transactions=[]

    for _, row in encoding.iterrows():
        items=[x.strip() for x in str(row["Kategori Layanan"]).replace(";", ",").split(",") if x.strip()]
        items=list(dict.fromkeys(items))
        transactions.append(items)

    total=len(transactions)

    # frequent itemset manual untuk kategori kecil (6 layanan)
    from itertools import combinations

    item_counts={}
    for basket in transactions:
        for item in basket:
            item_counts[(item,)]=item_counts.get((item,),0)+1

    max_len=3
    for basket in transactions:
        for size in range(2, min(max_len,len(basket))+1):
            for combo in combinations(sorted(basket), size):
                item_counts[combo]=item_counts.get(combo,0)+1

    frequent_rows=[]
    for items,count in item_counts.items():
        support=count/total if total else 0
        if support >= 0.05:
            frequent_rows.append({
                "itemsets":"; ".join(items),
                "support":support,
                "jumlah_item":len(items),
                "jumlah_transaksi":count
            })

    frequent=pd.DataFrame(frequent_rows)
    if not frequent.empty:
        frequent=frequent.sort_values(
            ["jumlah_item","support"],
            ascending=[True,False]
        ).reset_index(drop=True)

    # association rule hanya 2 itemset agar sesuai penelitian.
    # Rule wajib memenuhi support >= 5%, confidence >= 50%, lift > 1.
    rule_rows=[]
    for items,count in item_counts.items():
        if len(items)==2:
            a,b=items
            sup_ab=count/total
            sup_a=item_counts.get((a,),0)/total
            sup_b=item_counts.get((b,),0)/total

            if sup_a and sup_b:
                conf_ab=sup_ab/sup_a
                conf_ba=sup_ab/sup_b
                lift_ab=conf_ab/sup_b
                lift_ba=conf_ba/sup_a

                if sup_ab>=0.05 and conf_ab>=0.50 and lift_ab>1:
                    rule_rows.append({
                        "Antecedent":a,
                        "Consequent":b,
                        "Support":sup_ab,
                        "Confidence":conf_ab,
                        "Lift":lift_ab
                    })

                if sup_ab>=0.05 and conf_ba>=0.50 and lift_ba>1:
                    rule_rows.append({
                        "Antecedent":b,
                        "Consequent":a,
                        "Support":sup_ab,
                        "Confidence":conf_ba,
                        "Lift":lift_ba
                    })

    rules=pd.DataFrame(rule_rows)

    if not rules.empty:
        rules=rules.drop_duplicates().sort_values(
            ["Lift","Confidence","Support"],
            ascending=False
        ).reset_index(drop=True)

    # ============================================================
    # REKOMENDASI PENELITIAN
    # Bundling dan Cross-selling TIDAK mengambil frequent itemset.
    # Hanya association rule hasil evaluasi yang digunakan.
    # ============================================================
    bundling=pd.DataFrame(columns=["Kombinasi Layanan","Support","Confidence","Lift"])
    cross=pd.DataFrame(columns=["Layanan Awal","Layanan Tambahan","Support","Confidence","Lift"])

    if not rules.empty:
        selected_rules = rules.copy()

        # Hindari rekomendasi yang terlalu jarang muncul.
        # Support 5% pada 214 transaksi = minimal sekitar 11 transaksi.
        selected_rules = selected_rules[
            (selected_rules["Support"] >= 0.05) &
            (selected_rules["Confidence"] >= 0.50) &
            (selected_rules["Lift"] > 1.00)
        ]

        # Ranking sesuai penelitian:
        # Lift -> Confidence -> Support
        selected_rules = selected_rules.sort_values(
            ["Lift", "Confidence", "Support"],
            ascending=False
        ).drop_duplicates(
            subset=["Antecedent", "Consequent"]
        ).reset_index(drop=True)

        # Rekomendasi akhir penelitian hanya menampilkan rule terbaik.
        # Tidak menampilkan seluruh frequent pattern.
        selected_rules = selected_rules.head(2)

        bundling = selected_rules.copy()
        bundling["Kombinasi Layanan"] = (
            bundling["Antecedent"] + " + " + bundling["Consequent"]
        )
        bundling = bundling[
            ["Kombinasi Layanan", "Support", "Confidence", "Lift"]
        ]

        cross = selected_rules.copy()
        cross = cross.rename(columns={
            "Antecedent": "Layanan Awal",
            "Consequent": "Layanan Tambahan"
        })[
            ["Layanan Awal", "Layanan Tambahan", "Support", "Confidence", "Lift"]
        ]

    return frequent, rules, bundling, cross



def service_distribution(encoding):
    """
    Menghitung jumlah layanan per transaksi berdasarkan basket asli.
    Tidak menggunakan frequent itemset karena dapat menyebabkan seluruh
    transaksi terbaca sebagai multi-layanan.
    """

    if "Kategori Layanan" in encoding.columns:
        baskets = encoding["Kategori Layanan"].fillna("").astype(str)
        jumlah = baskets.apply(
            lambda x: len(set([i.strip() for i in x.replace(";", ",").split(",") if i.strip()]))
        )
    else:
        cols = [c for c in encoding.columns if c != "Nomor Transaksi"]
        numeric = encoding[cols].apply(pd.to_numeric, errors="coerce").fillna(0)
        jumlah = numeric.sum(axis=1)

    kategori = jumlah.apply(
        lambda x: "1 Layanan" if x == 1 else ("2 Layanan" if x == 2 else "3+ Layanan")
    )

    result = kategori.value_counts().reindex(
        ["1 Layanan", "2 Layanan", "3+ Layanan"], fill_value=0
    ).reset_index()
    result.columns = ["Kategori", "Jumlah"]
    return result


def rank_recommendations(df, sort_col_index):
    """
    Urutkan dataframe rekomendasi (bundling/cross-selling) berdasarkan kolom
    numerik (mis. Lift atau Confidence) bila tersedia, agar paket yang paling
    kuat asosiasinya tampil sebagai prioritas utama. Nilai numerik ini TIDAK
    ditampilkan ke pengguna, hanya dipakai untuk menentukan urutan.
    Jika kolom tidak dapat dibaca sebagai angka, urutan asli dari file tetap
    dipertahankan (tidak ada data yang diubah/direkayasa).
    """
    if df is None or df.empty or sort_col_index >= len(df.columns):
        return df

    ranked = df.copy()
    numeric_key = pd.to_numeric(ranked.iloc[:, sort_col_index], errors="coerce")

    if numeric_key.notna().sum() > 0:
        ranked = (
            ranked.assign(_sort_key=numeric_key)
            .sort_values("_sort_key", ascending=False, na_position="last")
            .drop(columns="_sort_key")
            .reset_index(drop=True)
        )

    return ranked


def detect_period(encoding_df):
    """
    Mendeteksi periode data transaksi secara otomatis dari pola tahun
    (4 digit, 19xx/20xx) yang terdapat pada kolom Nomor Transaksi.
    Dibuat generik (bukan tahun yang di-hardcode) agar tetap akurat
    apabila dataset diperbarui di kemudian hari.
    """
    if encoding_df is None or "Nomor Transaksi" not in encoding_df.columns:
        return None

    matches = encoding_df["Nomor Transaksi"].astype(str).str.findall(r"(?:19|20)\d{2}")
    years = [int(y) for sub in matches for y in sub]

    if not years:
        return None

    y_min, y_max = min(years), max(years)
    return f"{y_min}" if y_min == y_max else f"{y_min}\u2013{y_max}"


def create_business_excel(bundling_ranked, cross_ranked, periode, total):
    """
    Menyusun file unduhan hasil yang disesuaikan dengan kebutuhan perusahaan:
    hanya memuat rekomendasi paket bundling dan cross-selling yang sudah
    diurutkan berdasarkan prioritas, TANPA nilai teknis Support/Confidence/
    Lift, sehingga langsung dapat dipakai oleh tim sales/manajemen.
    """
    wb = Workbook()
    ws = wb.active
    ws.title = "Rekomendasi"

    labels = ["Prioritas Utama", "Prioritas Alternatif"]

    ws.append(["Rekomendasi Strategi Layanan Delite Indonesia"])
    ws.append([f"Periode Data: {periode or '-'}", f"Total Transaksi: {total}"])
    ws.append([])

    ws.append(["PAKET BUNDLING PRIORITAS"])
    ws.append(["Prioritas", "Kombinasi Layanan", "Catatan"])
    header_row_1 = ws.max_row
    if bundling_ranked is not None:
        for i, row in bundling_ranked.head(2).reset_index(drop=True).iterrows():
            label = labels[i] if i < len(labels) else f"Paket {i+1}"
            ws.append([
                label,
                format_item(row.iloc[0]),
                "Pertimbangkan sebagai paket penawaran pelanggan."
            ])

    ws.append([])
    ws.append(["REKOMENDASI CROSS-SELLING"])
    ws.append(["Prioritas", "Layanan Awal", "Layanan Tambahan"])
    header_row_2 = ws.max_row
    if cross_ranked is not None:
        for i, row in cross_ranked.head(2).reset_index(drop=True).iterrows():
            label = labels[i] if i < len(labels) else f"Peluang {i+1}"
            tambahan = row.iloc[1] if len(row) > 1 else "-"
            ws.append([label, row.iloc[0], tambahan])

    for r in (header_row_1, header_row_2):
        for cell in ws[r]:
            cell.font = Font(bold=True, color="FFFFFF")
            cell.fill = PatternFill("solid", fgColor="1F4E78")

    for col in ["A", "B", "C"]:
        ws.column_dimensions[col].width = 32

    out = io.BytesIO()
    wb.save(out)
    out.seek(0)
    return out


