def read_flexible_dataset(uploaded_file):
    """
    Engine input dinamis.
    Dashboard bekerja dari dataset mentah transaksi.
    Selama tersedia 4 kolom:
    - Nomor Transaksi
    - Kategori Layanan
    - Item/Deskripsi Item
    - Client

    Analisis FP-Growth dibuat ulang di dalam Streamlit agar hasil konsisten
    dengan data mentah dan tidak bergantung pada output Google Colab.
    """

    import pandas as pd

    name = getattr(uploaded_file, "name", "").lower()

    if name.endswith(".csv"):
        df = pd.read_csv(uploaded_file)
    else:
        xls = pd.ExcelFile(uploaded_file)
        df = pd.read_excel(uploaded_file, sheet_name=xls.sheet_names[0])

    df.columns = (
        df.columns.astype(str)
        .str.strip()
        .str.replace("\n", " ", regex=False)
    )

    mapping = {}

    for col in df.columns:
        c = col.lower().strip()

        if "nomor" in c and "transaksi" in c:
            mapping["Nomor Transaksi"] = col
        elif "kategori" in c and "layanan" in c:
            mapping["Kategori Layanan"] = col
        elif c == "item" or "deskripsi" in c:
            mapping["Item"] = col
        elif "client" in c or "customer" in c:
            mapping["Client"] = col

    required = [
        "Nomor Transaksi",
        "Kategori Layanan",
        "Item",
        "Client"
    ]

    missing = [x for x in required if x not in mapping]

    if missing:
        raise Exception(
            "Dataset tidak sesuai. Gunakan 4 kolom: "
            "Nomor Transaksi, Kategori Layanan, Item, Client."
        )

    raw = pd.DataFrame({
        "Nomor Transaksi": df[mapping["Nomor Transaksi"]].fillna("").astype(str).str.strip(),
        "Kategori Layanan": df[mapping["Kategori Layanan"]].fillna("").astype(str).str.strip(),
        "Item": df[mapping["Item"]].fillna("").astype(str).str.strip(),
        "Client": df[mapping["Client"]].fillna("").astype(str).str.strip()
    })

    raw = raw[raw["Nomor Transaksi"] != ""].copy()

    raw["Kategori Layanan"] = raw["Kategori Layanan"].apply(clean_category)

    # Buang transaksi kosong agar FP-Growth membaca basket asli
    raw = raw[
        raw["Kategori Layanan"].astype(str).str.strip() != ""
    ].reset_index(drop=True)

    frequent, rules, bundling, cross = generate_analysis_from_raw(raw)

    warnings = [
        f"Dataset diterima : {len(raw)} transaksi.",
    ]

    return raw, frequent, rules, bundling, cross, warnings, "raw"


def format_percent(value):
    try:
        return f"{float(value)*100:.2f}%"
    except:
        return value


def prepare_academic_display(frequent, rules):
    """
    Format tabel academic agar sesuai laporan penelitian.
    """
    f = frequent.copy()
    r = rules.copy()

    if "support" in f.columns:
        f["support"] = (f["support"] * 100).round(2).astype(str) + "%"

    f = f.rename(columns={
        "itemsets": "Itemset (kombinasi layanan yang muncul bersama)",
        "support": "Support (persentase kemunculan pola)",
        "jumlah_item": "Jumlah Layanan",
        "jumlah_transaksi": "Jumlah Transaksi"
    })

    if "support" in r.columns:
        r["support"] = (r["support"] * 100).round(2).astype(str) + "%"
    if "confidence" in r.columns:
        r["confidence"] = (r["confidence"] * 100).round(2).astype(str) + "%"
    if "lift" in r.columns:
        r["lift"] = r["lift"].round(3)

    r = r.rename(columns={
        "antecedents": "Antecedent (layanan awal/pemicu)",
        "consequents": "Consequent (layanan yang cenderung muncul bersama)",
        "support": "Support (persentase transaksi yang memuat pola)",
        "confidence": "Confidence (tingkat keyakinan hubungan layanan)",
        "lift": "Lift (kekuatan hubungan dibanding pola acak)"
    })

    return f, r


def prepare_business_display(data):
    """
    Format tabel bisnis tanpa mengubah nilai analisis.
    """
    d = data.copy()
    for col in ["support", "confidence"]:
        if col in d.columns:
            d[col] = (d[col] * 100).round(2).astype(str) + "%"
    if "lift" in d.columns:
        d["lift"] = d["lift"].round(3)
    return d

